#!/bin/bash\n\n#############################################################################\n# Supabase Edge Functions Deployment Script\n#############################################################################\n# This script deploys all three secure Edge Functions to Supabase\n# Required: Supabase CLI installed (npm install -g supabase)\n#\n# Usage:\n#   chmod +x scripts/deploy-edge-functions.sh\n#   ./scripts/deploy-edge-functions.sh\n#\n# Prerequisites:\n#   1. Supabase CLI must be installed\n#   2. Must be logged into Supabase: supabase login\n#   3. Project link must be configured: supabase link --project-ref <ref>\n#############################################################################\n\nset -e\n\necho \"🚀 Supabase Edge Functions Deployment\"\necho \"======================================\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Check if Supabase CLI is installed\nif ! command -v supabase &> /dev/null; then\n    echo -e \"${RED}❌ Supabase CLI is not installed${NC}\"\n    echo \"Install it with: npm install -g supabase\"\n    exit 1\nfi\n\necho -e \"${GREEN}✓ Supabase CLI found${NC}\"\n\n# Check if we're in the right directory\nif [ ! -d \"supabase/functions\" ]; then\n    echo -e \"${RED}❌ supabase/functions directory not found${NC}\"\n    echo \"Make sure you're running this from the project root directory\"\n    exit 1\nfi\n\necho -e \"${GREEN}✓ Project structure verified${NC}\"\necho \"\"\n\n# Deploy crb-check function\necho -e \"${YELLOW}📦 Deploying crb-check function...${NC}\"\nsupabase functions deploy crb-check --no-verify\nif [ $? -eq 0 ]; then\n    echo -e \"${GREEN}✓ crb-check deployed successfully${NC}\"\nelse\n    echo -e \"${RED}❌ Failed to deploy crb-check${NC}\"\n    exit 1\nfi\necho \"\"\n\n# Deploy payroll-integration function\necho -e \"${YELLOW}📦 Deploying payroll-integration function...${NC}\"\nsupabase functions deploy payroll-integration --no-verify\nif [ $? -eq 0 ]; then\n    echo -e \"${GREEN}✓ payroll-integration deployed successfully${NC}\"\nelse\n    echo -e \"${RED}❌ Failed to deploy payroll-integration${NC}\"\n    exit 1\nfi\necho \"\"\n\n# Deploy admin-settings function\necho -e \"${YELLOW}📦 Deploying admin-settings function...${NC}\"\nsupabase functions deploy admin-settings --no-verify\nif [ $? -eq 0 ]; then\n    echo -e \"${GREEN}✓ admin-settings deployed successfully${NC}\"\nelse\n    echo -e \"${RED}❌ Failed to deploy admin-settings${NC}\"\n    exit 1\nfi\necho \"\"\n\necho -e \"${GREEN}✅ All Edge Functions deployed successfully!${NC}\"\necho \"\"\necho -e \"${YELLOW}Next steps:${NC}\"\necho \"1. Set environment variables (see scripts/set-env-vars.sh)\"\necho \"2. Test the functions in Supabase Dashboard\"\necho \"3. Verify frontend can invoke them successfully\"\necho \"\"\n"